insert into public.packs (id, version, sector, description, config) values
  ('fauna-camtrap', '0.4.0', 'fauna', 'Paquete cámaras trampa (LILA CDLA). Prompt primario ''coyote'' con fallbacks [''animal'',''fox'',''dog''] si SAM no detecta. Persona se difumina por caja SAM (sin face ID). Dedup de reentrada configurable.', '{"id": "fauna-camtrap", "version": "0.4.0", "locale": "es-CR", "jurisdiction": "global", "description": "Paquete cámaras trampa (LILA CDLA). Prompt primario ''coyote'' con fallbacks [''animal'',''fox'',''dog''] si SAM no detecta. Persona se difumina por caja SAM (sin face ID). Dedup de reentrada configurable.", "targets": [{"prompt": "coyote", "class": "coyote", "fallbacks": ["animal", "fox", "dog"]}, {"prompt": "person", "class": "persona"}], "sampling": {"fps": 5, "mode": "video_track", "chunk_s": 60, "overlap_s": 2}, "geometry": {"zones": [{"id": "frame_completo", "polygon": [[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]]}], "lines": []}, "metrics": ["unique_count", "dwell"], "dedup": {"iou_stitch": 0.3, "reentry_window_s": 20, "reentry_edge_px": 80, "center_dist_factor": 2.0, "edge_dist_factor": 4.0}, "alerts": [{"id": "persona_noche", "when": "class == ''persona'' AND local_hour NOT IN 6..18", "severity": "alta", "message": "Persona detectada de noche en la estación {station}"}, {"id": "especie_objetivo", "when": "class == ''coyote'' AND unique_count >= 1", "severity": "info", "message": "Registro de {class}: {unique_count} individuos"}], "voice": {"languages": ["es", "en"], "link_by": ["timestamp", "station"]}, "report": {"template": "fauna_estacion_v1", "sections": ["resumen", "especies", "eventos", "notas_campo", "alertas"]}, "privacy": {"blur": ["persona"], "store": "aggregates_and_blurred_clips", "identity": false, "blur_radius": 28}, "station_defaults": {"station": "demo-seattleish", "local_tz_offset_hours": -8}, "output": {"annotated_video": true, "blurred_video": true}}'::jsonb),
  ('multitudes-densidad', '0.1.0', 'multitudes', 'Densidad de personas por zona en frames muestreados (modo imagen de SAM, sin límite de 16). No sigue individuos ni reconoce caras: solo cuántos, no quiénes.', '{"id": "multitudes-densidad", "version": "0.1.0", "locale": "es-CR", "jurisdiction": "global", "description": "Densidad de personas por zona en frames muestreados (modo imagen de SAM, sin límite de 16). No sigue individuos ni reconoce caras: solo cuántos, no quiénes.", "targets": [{"prompt": "person", "class": "persona"}], "sampling": {"fps": 1, "mode": "image_sample"}, "geometry": {"zones": [{"id": "zona_1", "polygon": [[0.1, 0.4], [0.9, 0.4], [0.9, 0.95], [0.1, 0.95]], "area_m2": 25}], "lines": []}, "metrics": ["persons_per_zone", "density_per_m2", "peak_density"], "density": {"point": "bbox_bottom_center", "smoothing_window_s": 5, "sustain_s": 10}, "alerts": [{"id": "densidad_media", "when": "density_per_m2 >= 4 SUSTAINED sustain_s", "severity": "media", "message": "Densidad de {density_per_m2} personas/m² en {zone} durante {sustain_s} s"}, {"id": "densidad_alta", "when": "density_per_m2 >= 6 SUSTAINED sustain_s", "severity": "alta", "message": "Densidad crítica de {density_per_m2} personas/m² en {zone}: abrir salida o frenar el ingreso"}], "voice": {"languages": ["es", "en"], "link_by": ["timestamp", "station"]}, "report": {"template": "multitudes_evento_v1", "sections": ["resumen", "pico_por_zona", "alertas", "notas_campo", "limites"]}, "privacy": {"blur": ["persona"], "blur_target": "full_bbox", "store": "aggregates_only", "identity": false, "tracking": false, "blur_radius": 28}, "station_defaults": {"station": "demo-multitudes", "local_tz_offset_hours": -6}, "output": {"annotated_video": true, "blurred_video": true, "heatmap": true}}'::jsonb),
  ('transito-giros', '0.1.0', 'transito', 'Matriz de giros N/S/E/O en intersección. SAM por recorte de acceso (tope 16 objs/frame). budget_usd 0.50. Encudre calibrado para data/transit/wicker_park_intersection (vista cenital). Conteos NOT VERIFIED hasta QA.', '{"id": "transito-giros", "version": "0.1.0", "locale": "es-CR", "jurisdiction": "global", "description": "Matriz de giros N/S/E/O en intersección. SAM por recorte de acceso (tope 16 objs/frame). budget_usd 0.50. Encudre calibrado para data/transit/wicker_park_intersection (vista cenital). Conteos NOT VERIFIED hasta QA.", "targets": [{"prompt": "car", "class": "car", "fallbacks": ["vehicle", "automobile"]}, {"prompt": "motorcycle", "class": "motorcycle", "fallbacks": ["motorbike", "scooter"]}, {"prompt": "bus", "class": "bus"}, {"prompt": "truck", "class": "truck", "fallbacks": ["van", "pickup"]}, {"prompt": "bicycle", "class": "bicycle", "fallbacks": ["bike", "cyclist"]}, {"prompt": "person", "class": "person", "fallbacks": ["pedestrian", "people"]}], "sampling": {"fps": 5, "mode": "video_track", "chunk_s": 60, "overlap_s": 2}, "budget_usd": 0.5, "access_crops": true, "geometry": {"approaches": [{"id": "acceso_N", "line": [[0.3, 0.34], [0.7, 0.34]], "roi": [0.28, 0.0, 0.72, 0.36]}, {"id": "acceso_S", "line": [[0.3, 0.66], [0.7, 0.66]], "roi": [0.28, 0.64, 0.72, 1.0]}, {"id": "acceso_E", "line": [[0.66, 0.3], [0.66, 0.7]], "roi": [0.64, 0.28, 1.0, 0.72]}, {"id": "acceso_O", "line": [[0.34, 0.3], [0.34, 0.7]], "roi": [0.0, 0.28, 0.36, 0.72]}], "lines": [], "zones": []}, "metrics": ["turning_movements", "unique_count", "dwell"], "turning_rules": {"_": "por_orientacion"}, "dedup": {"iou_stitch": 0.3, "reentry_window_s": 15, "reentry_edge_px": 80, "center_dist_factor": 2.0, "edge_dist_factor": 4.0}, "alerts": [{"id": "flujo_alto_autos", "when": "class == ''car'' AND unique_count >= 20", "severity": "media", "message": "Flujo alto de autos en {station}: {unique_count} únicos"}, {"id": "presencia_peatones", "when": "class == ''person'' AND unique_count >= 5", "severity": "info", "message": "Peatones en intersección {station}: {unique_count}"}, {"id": "motos_presentes", "when": "class == ''motorcycle'' AND unique_count >= 3", "severity": "info", "message": "Motos detectadas en {station}: {unique_count}"}], "voice": {"languages": ["es", "en"], "link_by": ["timestamp", "station"]}, "report": {"template": "transito_interseccion_v1", "sections": ["resumen", "matriz_giros", "por_clase", "alertas", "limites"]}, "privacy": {"blur": ["person"], "blur_target": "full_bbox", "store": "aggregates_and_blurred_clips", "identity": false, "blur_radius": 28}, "station_defaults": {"station": "wicker-park", "local_tz_offset_hours": -5}, "output": {"annotated_video": true, "blurred_video": true}}'::jsonb)
